// Package openapi turns the Swagger 2.0 document generated by swag into an
// OpenAPI 3 document for Swagger UI. OpenAPI 3 allows several named request
// body examples, which Swagger UI shows as a dropdown.
package openapi

import (
	"context"
	"encoding/json"
	"fmt"

	"github.com/getkin/kin-openapi/openapi2"
	"github.com/getkin/kin-openapi/openapi2conv"
	"github.com/getkin/kin-openapi/openapi3"
)

// ExtractPath is the operation that gets ExtractExamples.
const ExtractPath = "/api/v1/extract"

// FromSwagger2 converts a Swagger 2.0 JSON document to OpenAPI 3, points
// the server at the origin the UI was loaded from, and adds the extract
// examples. The result is validated before it is returned.
func FromSwagger2(v2 []byte) ([]byte, error) {
	var doc2 openapi2.T
	if err := json.Unmarshal(v2, &doc2); err != nil {
		return nil, fmt.Errorf("parse swagger 2.0 doc: %w", err)
	}
	doc3, err := openapi2conv.ToV3(&doc2)
	if err != nil {
		return nil, fmt.Errorf("convert to openapi 3: %w", err)
	}

	// A relative server makes the UI call the server it was loaded from,
	// over the same scheme.
	doc3.Servers = openapi3.Servers{{URL: "/"}}

	if err := addExtractExamples(doc3); err != nil {
		return nil, err
	}
	if err := doc3.Validate(context.Background()); err != nil {
		return nil, fmt.Errorf("openapi 3 doc is invalid: %w", err)
	}
	return json.Marshal(doc3)
}

// ExampleKey is the spec key of ExtractExamples[i], e.g. "01-badomjip".
func ExampleKey(i int) string {
	return fmt.Sprintf("%02d-%s", i+1, ExtractExamples[i].Key)
}

func addExtractExamples(doc *openapi3.T) error {
	item := doc.Paths.Find(ExtractPath)
	if item == nil || item.Post == nil || item.Post.RequestBody == nil || item.Post.RequestBody.Value == nil {
		return fmt.Errorf("POST %s with a request body is not in the doc", ExtractPath)
	}
	media := item.Post.RequestBody.Value.Content.Get("application/json")
	if media == nil {
		return fmt.Errorf("POST %s has no application/json body", ExtractPath)
	}
	media.Examples = make(openapi3.Examples, len(ExtractExamples))
	for i, ex := range ExtractExamples {
		e := openapi3.NewExample(map[string]any{"url": ex.URL, "request_id": ex.RequestID})
		e.Summary = ex.Summary
		e.Description = ex.Description
		// JSON sorts map keys and Swagger UI lists examples in that order
		// (showing the summary), so the index keeps ExtractExamples' order.
		media.Examples[ExampleKey(i)] = &openapi3.ExampleRef{Value: e}
	}
	// Swagger UI pre-fills the body from example, which would win over the
	// dropdown; the schema's property examples still document the fields.
	media.Example = nil
	return nil
}
